layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying float vTh, vY, vU, vR, vK, vFace;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 1.30){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float H = 2.7, y = (position.y + .5)*H, yn = y/H;
      vec2 d = normalize(position.xz); float th = atan(d.y, d.x);
      float r = mix(.36, .62, aK) + .12*yn
              + .07*sin(th*3. + y*1.9 + aK*4.1 + u*1.3)*sin(y*1.3 - th*2. + aK*2.7);   // irregular, breathing radius
      vec3 wp = aO + vec3(d.x*r, y + .02, d.y*r);
      vec3 V = normalize(cameraPosition - wp);
      vFace = abs(dot(vec3(d.x, 0., d.y), V));                   // 0 where the surface is edge-on to the camera
      vTh = th; vY = y; vU = u; vR = r; vK = aK;
      gl_Position = projectionMatrix*viewMatrix*vec4(wp, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vTh, vY, vU, vR, vK, vFace;
    float h2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h2(i), h2(i + vec2(1,0)), f.x), mix(h2(i + vec2(0,1)), h2(i + vec2(1,1)), f.x), f.y); }
    void main(){
      float y = vY, u = vU, H = 2.7, yn = y/H, TAU = 6.28318;
      float rise = (1. - pow(1. - clamp(u/.6, 0., 1.), 2.))*H;      // climbs from the feet, past the head
      float clear = max(u - .45, 0.)/.65*H;                          // the base clears first, the top goes last
      float d = 0.;
      for (int i=0;i<5;i++){
        float fi = float(i) + vK*5.;
        float pitch = 1.3 + .9*fract(fi*.618);                      // every wisp winds at its own rate
        float c = fi*TAU/5. + vK*.63 + y*pitch + u*.9 + (vn(vec2(y*1.6 - u*2., fi*3.)) - .5)*1.1;
        float da = mod(vTh - c + 3.14159, TAU) - 3.14159;
        float w = (.033 + .06*yn)*(.8 + .4*fract(fi*.37));
        float brk = smoothstep(.4, .75, vn(vec2(y*2.2 - u*4. + fi*5.7, fi)));
        d += exp(-pow(abs(da*vR)/w, 1.4))*brk*(.55 + .45*fract(fi*.37));
      }
      float mask = smoothstep(rise + .02, rise - .15, y)*smoothstep(clear - .05, clear + .25, y);
      float fade = (1. - smoothstep(.95, 1.30, u))*smoothstep(0., .08, y)*(1. - smoothstep(.75, .97, yn));
      float face = smoothstep(.06, .45, vFace);                   // no bright vertical outline at the silhouette
      float k = d*mask*fade*face*(1. - .5*yn)*mix(.13, .095, vK);
      vec3 outc = mix(uGold, vec3(1., .97, .92), .55)*k;           // pale warm air, not flame
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
